#!/bin/bash
# Uninstall script for Chromium
# Generated by IntuneBrew

# Exit on error
set -e

echo "Uninstalling Chromium..."

# Check if running as root
if [ "$EUID" -ne 0 ]; then
  echo "Please run as root"
  exit 1
fi

# Kill application process if running
echo "Stopping Chromium if running..."
pkill -f "Chromium" 2>/dev/null || true

# Remove /Applications/chrome-mac/Chromium.app
echo "Removing /Applications/chrome-mac/Chromium.app..."
if [ -d "/Applications/chrome-mac/Chromium.app" ]; then
    rm -rf "/Applications/chrome-mac/Chromium.app" 2>/dev/null || true
elif [ -f "/Applications/chrome-mac/Chromium.app" ]; then
    rm -f "/Applications/chrome-mac/Chromium.app" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/Chromium
echo "Removing $HOME/Library/Application Support/Chromium..."
if [ -d "$HOME/Library/Application Support/Chromium" ]; then
    rm -rf "$HOME/Library/Application Support/Chromium" 2>/dev/null || true
elif [ -f "$HOME/Library/Application Support/Chromium" ]; then
    rm -f "$HOME/Library/Application Support/Chromium" 2>/dev/null || true
fi

# Remove $HOME/Library/Application Support/CrashReporter/Chromium_*.plist
echo "Removing $HOME/Library/Application Support/CrashReporter/Chromium_*.plist..."
