# Remove $HOME/Library/Logs/DiagnosticReports/Chromium-*.ips
echo "Removing $HOME/Library/Logs/DiagnosticReports/Chromium-*.ips..."
if [ -d "$HOME/Library/Logs/DiagnosticReports/Chromium-*.ips" ]; then
    rm -rf "$HOME/Library/Logs/DiagnosticReports/Chromium-*.ips" 2>/dev/null || true
elif [ -f "$HOME/Library/Logs/DiagnosticReports/Chromium-*.ips" ]; then
